"use strict";(globalThis.webpackChunkmy_website||=[]).push([[66254],{15637(e){e.exports=JSON.parse('{"slug":"rewards","title":"Rewards","short":"Ada earned by delegators and stake pool operators for participating in the network.","category":"consensus","aliases":[],"mentalModel":"A weekly paycheck from the network. Each epoch the protocol shares a slice of newly minted ada with every wallet that delegated stake to a productive pool; the size of the slice depends on the pool\'s performance and your share of its stake.","related":["delegation","epoch","stake-pool","pool-saturation","monetary-expansion-rate","treasury-cut"],"sources":[],"link":"/calculator","level":"beginner","body":"Rewards are calculated each epoch from the stake snapshot and the producing pool\'s performance, then paid out two epochs later once the protocol has finished accounting and distribution to every delegator and operator."}')}}]);